def stage(n):
    return (2+n)/2 if n>=0 else 2/(2-n)
def speed(p):
    return p['stats']['spe']*stage(p.get('stat_stages',{}).get('speed',0))*(.25 if p.get('status')=='paralysis' else 1)
def base_damage(a,b,m,crit=False):
    power,acc,t,cat,pri,cr=m
    if not power or cat=='status': return 0,0,False
    physical=cat=='physical'; ak,dk,ast,dst=('atk','def','attack','defense') if physical else ('spa','spd','sp_atk','sp_def')
    x=a.get('stat_stages',{}).get(ast,0); y=b.get('stat_stages',{}).get(dst,0)
    if crit: x=max(0,x); y=min(0,y)
    av=int(a['stats'][ak]*stage(x)); dv=max(1,int(b['stats'][dk]*stage(y)))
    raw=22*power*av//dv//50
    if physical and a.get('status')=='burn': raw=int(raw*.5)
    raw=(raw+2)*(2 if crit else 1)
    e=1
    for typ in b['types']: e*=CHART.get((t,typ),1)
    return raw,e,t in a['types']
def summary(a,b,m,hp,scale=1):
    # integrate normal and critical damage rolls; approximate floor effects exactly
    acc=m[1]/100*min(1,stage(a.get('stat_stages',{}).get('accuracy',0))/stage(b.get('stat_stages',{}).get('evasion',0)))
    cr=(.0625,.125,.25,.333,.5)[min(4,max(0,m[5]))]
    total=0; ko=0; uncapped=0
    for c,w in ((False,1-cr),(True,cr)):
        raw,e,stab=base_damage(a,b,m,c)
        for roll in (85,90,95,100):
            d=raw*roll//100
            if stab:d=d*3//2
            d=int(d*e*scale)
            total+=min(hp,d)*w/4; uncapped+=d*w/4; ko+=(d>=hp)*w/4
    return total*acc,ko*acc,uncapped*acc

def choose_move(state):
    a=state['active_pokemon']; b=dict(state['opponent_active']); b['stats']=STATS.get(b['species'],{'hp':150,'atk':100,'def':100,'spa':100,'spd':100,'spe':100}); hp=max(1,round(b['stats']['hp']*b['hp_percent']/100)); b['current_hp']=hp
    legal=state['legal_actions']; bench={p['index']:p for p in state['bench']}; live=[p for p in [a]+list(bench.values()) if p['current_hp']>0]; forced=not any(x['action']=='move' for x in legal)
    known=set(b.get('known_moves',[])); prior=set(PUBLIC_PRIORS.get(b['species'],()))
    # Historical public replay moves are priors, never assumed to be the actual current moveset.
    foes=[(MOVES[n],1 if n in known else PRIOR) for n in sorted(known|prior) if n in MOVES]
    if len(known)<4:
        foes += [((85,100,t,c,0,0),.65) for t in b['types'] for c in ('physical','special')]
    if not foes: foes=[((80,100,'normal','physical',0,0),1)]
    def enemy(p,health):
        rows=[]
        for m,w in foes:
            d,k,u=summary(b,p,m,health,1.05)
            rows.append((w*(d/health+1.0*k+.12*(m[4]>0)*k),d,k,u,m[4]))
        return max(rows,key=lambda x:x[0])
    def utility(p):
        # Resource value depends on combat stats, not fixed species or opponent lineup.
        s=p['stats']; return .6+.4*(s['atk']+s['spa']+s['spe'])/330
    def estimate(p,m,health):
        d,k,u=summary(p,b,m,hp,.96)
        _,inc,death,raw,pri=enemy(p,health)
        first=1 if (m[4],speed(p))>(pri,speed(b)) else (0.5 if (m[4],speed(p))==(pri,speed(b)) else 0)
        # Chance of surviving to attack, then expected HP trade. Reward a second turn if viable.
        acts=1-(1-first)*death
        retaliation=1-first*k
        loss=retaliation*(inc/max(1,p['max_hp'])+.5*death)*utility(p)
        next_hp=max(1,health-inc*retaliation)
        second=(1-death*retaliation)*(1-k)*min(1,u/max(1,hp-d))
        score=acts*(d/hp+1.15*k+.28*second)-PRESERVE*loss
        if first and death>.7 and k<.6: score-=RISK*(1-k)*utility(p)*.35
        return score
    def best(p,health):
        if health<=0:return -5
        return max([estimate(p,MOVES[m['identifier']],health) for m in p['moves'] if m['pp'] and m['identifier'] in MOVES]+[-3])
    options=[]
    for x in legal:
        if x['action']=='move':
            m=a['moves'][x['index']]; s=estimate(a,MOVES[m['identifier']],a['current_hp']) if m['identifier'] in MOVES else -5
        elif x['action']=='switch':
            p=bench[x['index']]; h=p['current_hp']; _,inc,death,raw,pri=enemy(p,h)
            if forced:s=best(p,h)
            else:
                s=best(p,h-inc)*(1-death)-PRESERVE*(inc/p['max_hp']+.5*death)*utility(p)-SWITCH
        else:s=-3
        options.append((s,x))
    return max(options,key=lambda x:x[0])[1] if options else {'action':'struggle'}
